<script setup>
import { ref } from 'vue';
import { Store } from '../store';
import Icon from './ui/EditionIcon.vue';
const code=ref(''),busy=ref(false),error=ref('');
async function login(){if(busy.value)return;error.value='';if(!/^\d{6}$/.test(code.value)){error.value='Enter the six-digit access code.';return;}busy.value=true;try{if(!await Store.posLogin(code.value))error.value='That access code is not valid for this company.';}finally{busy.value=false;}}
</script>
<template><div class="ed-login"><section class="ed-login-story"><div class="ed-brand"><span class="ed-brandmark"><i></i><i></i><i></i><i></i></span>myfin<small>pos</small></div><div><div class="ed-eyebrow">{{ Store.state.tenantContext?.workspace?.name }}</div><h1>{{ Store.state.tenantContext?.company?.name }}</h1><p>Fast access is limited to this company and this device session.</p><div class="ed-login-lines" aria-hidden="true"></div></div><footer class="ed-eyebrow">SECURE COMPANY POS ACCESS</footer></section><section class="ed-login-form"><div class="ed-eyebrow">POS ACCESS</div><h1>Ready for<br>the next sale.</h1><p class="ed-muted">Enter your personal six-digit code.</p><form @submit.prevent="login"><div class="ed-field"><label for="pos-code">Access code</label><input id="pos-code" v-model="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="000000" required></div><p v-if="error" class="ed-login-error" role="alert">{{ error }}</p><button class="ed-btn primary" type="submit" :disabled="busy">{{ busy?'Checking…':'Open POS workspace' }}<Icon name="arrow" /></button></form><router-link class="ed-btn" to="/overview">Sign in with email and password</router-link><footer>Administrative settings require password sign-in.</footer></section></div></template>
